/// <summary>
/// DebuC 16.10.23
/// last modified: PaffH 25.02.25
/// </summary>
/// <param name = "_buffer">NDXTmpUmsatzClassThreadControl</param>
/// <param name = "_info">NDXString100</param>
/// <param name = "_lIncActiveCounter">boolean</param>
static void setInfoStatic(
    NDXTmpUmsatzClassThreadControl _buffer,
    NDXString100 _info,
    boolean _lIncActiveCounter = false)
{
    System.Exception ex;
    NDXTmpUmsatzClassThreadControl nDXTmpUmsatzClassThreadControl;
    try
    {
        ttsbegin;
        nDXTmpUmsatzClassThreadControl = NDXTmpUmsatzClassThreadControl::findOrCreate(_buffer, true, true);
        nDXTmpUmsatzClassThreadControl.Info = _info;
        //nDXTmpUmsatzClassThreadControl.setInfo(_info);
        if (_lIncActiveCounter)
        {
            //nDXTmpUmsatzClassThreadControl.incActiveCounter();
            nDXTmpUmsatzClassThreadControl.ActiveCounter += 1;
        }
        nDXTmpUmsatzClassThreadControl.update();
        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
        {
            Error(strFmt("@NDXBase:NDXDeadLock", tableId2Name(nDXTmpUmsatzClassThreadControl.TableId)));
        }
        else
        {
            sleep(RandomGenerate::construct().randomInt(NDXExceptionConstants::RetryInterval100, NDXExceptionConstants::RetryInterval1000));
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
        {
            Error(strFmt("@NDXBase:NDXUpdateConflict", tableId2Name(nDXTmpUmsatzClassThreadControl.TableId)));
        }
        else
        {
            sleep(RandomGenerate::construct().randomInt(NDXExceptionConstants::RetryInterval100, NDXExceptionConstants::RetryInterval1000));
            retry;
        }
    }
    catch (ex)
    {
        Error(ex.Message);
    }
}

/// <summary>
/// DebuC 16.10.23
/// last modified: PaffH 19.02.25
/// </summary>
/// <param name = "_ThreadControl">NDXTmpUmsatzClassThreadControl</param>
/// <param name = "_forUpdate">boolean</param>
/// <param name = "_pessimisticLock">boolean</param>
/// <returns>NDXTmpUmsatzClassThreadControl</returns>
client server static public NDXTmpUmsatzClassThreadControl findOrCreate(
    NDXTmpUmsatzClassThreadControl _ThreadControl,
    boolean _forUpdate = false,
    boolean _pessimisticLock = false)
{
    NDXTmpUmsatzClassThreadControl nDXTmpUmsatzClassThreadControl = 
        NDXTmpUmsatzClassThreadControl::find(
        _ThreadControl.UmsSignature, 
        _ThreadControl.ThreadType, 
        _forUpdate,
        _pessimisticLock);

    boolean lNew = !nDXTmpUmsatzClassThreadControl.RecId;

    if (lNew)
    {
        try
        {
            ttsbegin;
            nDXTmpUmsatzClassThreadControl.data(_ThreadControl);
            nDXTmpUmsatzClassThreadControl = NDXTmpUmsatzClassThreadControl::create(nDXTmpUmsatzClassThreadControl);
            nDXTmpUmsatzClassThreadControl.write();
            ttscommit;
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch
        {
            throw Error("@NDXUmsAusw:NDXKumUmsError001");
        }
    }
    return nDXTmpUmsatzClassThreadControl;
}

/// <summary>
/// DebuC 16.10.23
/// last modified: PaffH 04.03.25
/// </summary>
/// <param name = "_umsSignature">NDXUmsSignature</param>
/// <param name = "_ThreadType">NDXThreadTypes</param>
/// <param name = "_forUpdate">boolean</param>
/// <param name = "_pessimisticLock">boolean</param>
/// <returns>NDXTmpUmsatzClassThreadControl</returns>
static NDXTmpUmsatzClassThreadControl find(
    NDXUmsSignature _umsSignature,
    NDXThreadTypes _ThreadType,
    boolean _forUpdate = false,
    boolean _pessimisticLock = false)
{
    NDXTmpUmsatzClassThreadControl threadControl;

    if (_umsSignature)
    {
        if (_forUpdate)
        {
            threadControl.selectForUpdate(_forUpdate);
        }
        if (_pessimisticLock)
        {
            threadControl.concurrencyModel(ConcurrencyModel::Pessimistic);
        }

        select firstonly threadControl
            where threadControl.UmsSignature == _umsSignature &&
            threadControl.ThreadType == _ThreadType;
    }
    return threadControl;
}

/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <param name = "_ThreadControl">NDXTmpUmsatzClassThreadControl</param>
/// <returns>NDXTmpUmsatzClassThreadControl</returns>
server static public NDXTmpUmsatzClassThreadControl create(NDXTmpUmsatzClassThreadControl _ThreadControl)
{
    ;
    try
    {
        ttsbegin;
        _ThreadControl.selectForUpdate(true);
        _ThreadControl.insert();
        ttscommit;
    }
    catch
    {
        throw Error(strfmt("@NDXUmsAusw:NDXKumUmsError002", _ThreadControl.ThreadType ));
    }

    return _ThreadControl;
}

/// <summary>
