void setInfo(NDXString100 info, boolean lSaveToHistory = false)
{
    #File
    int currentRetryCount;
    System.Exception ex;
    NDXTmpUmsatzClassThreadControl nDXTmpUmsatzClassThreadControl;
    try
    {
        ttsbegin;
        nDXTmpUmsatzClassThreadControl = NDXTmpUmsatzClassThreadControl::findOrCreate(this, true, true);
        nDXTmpUmsatzClassThreadControl.Info = info;
        if (lSaveToHistory)
        {
            nDXTmpUmsatzClassThreadControl.History    += info + #delimiterCRLF;
        }
        nDXTmpUmsatzClassThreadControl.write();
        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        currentRetryCount = xSession::currentRetryCount();
        if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
        {
            Error(strFmt("@NDXBase:NDXDeadLock", tableId2Name(nDXTmpUmsatzClassThreadControl.TableId)));
        }
        else
        {
            sleep(RandomGenerate::construct().randomInt(NDXExceptionConstants::RetryInterval500, NDXExceptionConstants::RetryInterval1000));
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        currentRetryCount = xSession::currentRetryCount();
        if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
        {
            Error(strFmt("@NDXBase:NDXUpdateConflict", tableId2Name(nDXTmpUmsatzClassThreadControl.TableId)));
        }
        else
        {
            sleep(RandomGenerate::construct().randomInt(NDXExceptionConstants::RetryInterval500, NDXExceptionConstants::RetryInterval1000));
            retry;
        }
    }
    catch (ex)
    {
        Error(ex.Message);
    }
}

/// <summary>
/// DebuC 16.10.23
/// last modified: PaffH 19.02.25
/// </summary>
/// <returns>ActiveCounter</returns>
int64 incActiveCounter()
{
    System.Exception ex;
    NDXTmpUmsatzClassThreadControl nDXTmpUmsatzClassThreadControl;
    try
    {
        ttsbegin;
        nDXTmpUmsatzClassThreadControl = NDXTmpUmsatzClassThreadControl::findOrCreate(this, true, true);
        nDXTmpUmsatzClassThreadControl.ActiveCounter += 1;
        nDXTmpUmsatzClassThreadControl.write();
        ttscommit;
        this.ActiveCounter = nDXTmpUmsatzClassThreadControl.ActiveCounter;
    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry10)
        {
            Error(strFmt("@NDXBase:NDXDeadLock", tableId2Name(nDXTmpUmsatzClassThreadControl.TableId)));
        }
        else
        {
            sleep(RandomGenerate::construct().randomInt(NDXExceptionConstants::RetryInterval500, NDXExceptionConstants::RetryInterval1000));
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry10)
        {
            Error(strFmt("@NDXBase:NDXUpdateConflict", tableId2Name(nDXTmpUmsatzClassThreadControl.TableId)));
        }
        else
        {
            sleep(RandomGenerate::construct().randomInt(NDXExceptionConstants::RetryInterval500, NDXExceptionConstants::RetryInterval1000));
            retry;
        }
    }
    catch (ex)
    {
        Error(ex.Message);
    }

    return this.ActiveCounter;
}

/// <summary>
/// DebuC 16.10.23
/// last modified: PaffH 26.02.25
/// </summary>
/// <param name = "_ThreadType">NDXThreadTypes</param>
/// <param name = "_UmsSignature">NDXUmsSignature</param>
static void ThreadStop(NDXThreadTypes  _ThreadType, NDXUmsSignature  _UmsSignature)
{
    int currentRetryCount;
    System.Exception ex;
    NDXTmpUmsatzClassThreadControl nDXTmpUmsatzClassThreadControl;
    try
    {
        NDXTmpUmsatzClassThreadControl threadControlParm;
        threadControlParm.ThreadType = _ThreadType;
        threadControlParm.UmsSignature  = _UmsSignature;
        ttsbegin;
        nDXTmpUmsatzClassThreadControl = NDXTmpUmsatzClassThreadControl::findOrCreate(threadControlParm, true, true);
        nDXTmpUmsatzClassThreadControl.ThreadEnd = DateTimeUtil::utcNow();
        nDXTmpUmsatzClassThreadControl.write();
        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        currentRetryCount = xSession::currentRetryCount();
        if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
        {
            Error(strFmt("@NDXBase:NDXDeadLock", tableId2Name(nDXTmpUmsatzClassThreadControl.TableId)));
        }
        else
        {
            sleep(RandomGenerate::construct().randomInt(NDXExceptionConstants::RetryInterval500, NDXExceptionConstants::RetryInterval1000));
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        currentRetryCount = xSession::currentRetryCount();
        if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
        {
            Error(strFmt("@NDXBase:NDXUpdateConflict", tableId2Name(nDXTmpUmsatzClassThreadControl.TableId)));
        }
        else
        {
            sleep(RandomGenerate::construct().randomInt(NDXExceptionConstants::RetryInterval500, NDXExceptionConstants::RetryInterval1000));
            retry;
        }
    }
    catch (ex)
    {
        Error(ex.Message);
    }
}

/// <summary>
/// DebuC 16.10.23
/// last modified: PaffH 19.02.25
/// </summary>
/// <param name = "_ThreadType">NDXThreadTypes</param>
/// <param name = "_contract">NDXUmsatzClassParmContract</param>
/// <returns>NDXTmpUmsatzClassThreadControl</returns>
static NDXTmpUmsatzClassThreadControl ThreadStart(NDXThreadTypes _ThreadType, NDXUmsatzClassParmContract _contract)
{
    System.Exception ex;
    NDXTmpUmsatzClassThreadControl threadControl;
    threadControl.ThreadType    = _ThreadType;
    threadControl.UmsSignature  = _contract.parmUmsSignature();
    threadControl = NDXTmpUmsatzClassThreadControl::findOrCreate(threadControl, true, true);
    boolean lNew = (threadControl.recVersion == 1);
    if (lNew)
    {
        try
        {
            ttsbegin;
            threadControl.selectForUpdate(true);
            threadControl.ThreadStart   = DateTimeUtil::utcNow();
            threadControl.ThreadEnd     = utcDateTimeNull();
            threadControl.ActiveCounter = 0;
            threadControl.Info          = '';
            threadControl.History       = '';
            threadControl.write();
            ttscommit;
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
            {
                Error(strFmt("@NDXBase:NDXDeadLock", tableId2Name(threadControl.TableId)));
            }
            else
            {
                sleep(NDXExceptionConstants::RetryInterval500);
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
            {
                Error(strFmt("@NDXBase:NDXUpdateConflict", tableId2Name(threadControl.TableId)));
            }
            else
            {
                sleep(NDXExceptionConstants::RetryInterval500);
                retry;
            }
        }
        catch (ex)
        {
            Error(ex.Message);
        }
    }
    if (_contract.parmRecIdNDXBatchProcessingTable())
    {
        NDXBatchProcessingTableProcess nDXBatchProcessingTableProcess;
        try
        {
            ttsbegin;
            nDXBatchProcessingTableProcess = NDXBatchProcessingTableProcess::findFromNDXBatchProcessingTableRecId(_contract.parmRecIdNDXBatchProcessingTable(), true);
            switch (_ThreadType)
            {
                case NDXThreadTypes::getValuesArtGrp:
                    nDXBatchProcessingTableProcess.ProcessStatus = NDXProcessStatus::GetValuesArtGrp;
                    break;
                case NDXThreadTypes::getValuesCust:
                    nDXBatchProcessingTableProcess.ProcessStatus = NDXProcessStatus::GetValuesCust;
                    break;
                case NDXThreadTypes::getValuesCS:
                    nDXBatchProcessingTableProcess.ProcessStatus = NDXProcessStatus::GetValuesCS;
                    break;
            }
            nDXBatchProcessingTableProcess.update();
            ttscommit;
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
            {
                Error(strFmt("@NDXBase:NDXDeadLock", tableId2Name(nDXBatchProcessingTableProcess.TableId)));
            }
            else
            {
                sleep(NDXExceptionConstants::RetryInterval500);
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
            {
                Error(strFmt("@NDXBase:NDXUpdateConflict", tableId2Name(nDXBatchProcessingTableProcess.TableId)));
            }
            else
            {
                sleep(NDXExceptionConstants::RetryInterval500);
                retry;
            }
        }
        catch (Exception::Error)
        {
            if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
            {
                Error(strFmt("@NDXBase:NDXTableError", tableId2Name(nDXBatchProcessingTableProcess.TableId)));
            }
            else
            {
                sleep(NDXExceptionConstants::RetryInterval500);
                retry;
            }
        }
        catch (ex)
        {
            str errorMessage = ex.Message + NDXGlobalConstants::NewLine;
            errorMessage += NDXHelperCommon::callStack2str();
            Error(errorMessage);
        }
    }

    return threadControl;
}
